ownedContracts.interfaceSketch:
// src/workflow/triage/types.ts — union extended, not replaced
type SizeClass = 'epic' | 'feature' | 'small' | 'trivial' | 'bugfix';

// bugfix is the only category whose route depends on a sub-magnitude
type BugfixMagnitude = 'small' | 'sized'; // 'small' -> skip design; 'sized' -> M/L design path

interface BugfixTriageResult {
  sizeClass: 'bugfix';
  magnitude: BugfixMagnitude;
}

interface TriageRoute {
  startStage: WorkflowName;   // 'issue' for bugfix
  standalone: boolean;
  needsPlan: boolean;         // sized -> true, small -> false
  producesLld: boolean;       // sized -> true, small -> false
}

// classify.ts — pure mapping, bugfix branch reads magnitude
declare function routeForSizeClass(
  sizeClass: SizeClass,
  magnitude?: BugfixMagnitude,
): TriageRoute;

